const crypto = require('crypto');
const db = require('../db');

const OTP_CONFIG = {
  length: 6,
  expiryMinutes: 10,
  maxAttempts: 3,
  cooldownMinutes: 1,
};

class OTPService {
  /**
   * Generate a secure 6-digit OTP
   */
  generateOTP() {
    return crypto.randomInt(100000, 999999).toString();
  }

  /**
   * Determine delivery method based on user data
   * Priority: Email > SMS
   */
  getDeliveryMethod(user) {
    if (user.email && user.email_verified) {
      return { method: 'email', destination: user.email };
    }

    if (user.phone && user.phone_verified) {
      return { method: 'sms', destination: user.phone };
    }

    // For new registrations - use whatever is provided
    if (user.email) {
      return { method: 'email', destination: user.email };
    }

    if (user.phone) {
      return { method: 'sms', destination: user.phone };
    }

    throw new Error('No valid contact method available');
  }

  /**
   * Create and store OTP in database
   */
  async createOTP(userId, method, purpose) {
    // Check cooldown - prevent spam
    const recentOTP = await db.query(
      `SELECT created_at FROM otp_tokens 
       WHERE user_id = $1 
         AND purpose = $2 
         AND created_at > NOW() - INTERVAL '${OTP_CONFIG.cooldownMinutes} minutes'
         AND is_used = FALSE
       ORDER BY created_at DESC 
       LIMIT 1`,
      [userId, purpose]
    );

    if (recentOTP.rows.length > 0) {
      const waitSeconds = Math.ceil(
        OTP_CONFIG.cooldownMinutes * 60 -
          (Date.now() - new Date(recentOTP.rows[0].created_at)) / 1000
      );
      throw new Error(`Please wait ${waitSeconds} seconds before requesting a new OTP`);
    }

    // Invalidate previous unused OTPs for same purpose
    await db.query(
      `UPDATE otp_tokens 
       SET is_used = TRUE 
       WHERE user_id = $1 AND purpose = $2 AND is_used = FALSE`,
      [userId, purpose]
    );

    const otpCode = this.generateOTP();
    const expiresAt = new Date(Date.now() + OTP_CONFIG.expiryMinutes * 60 * 1000);

    const result = await db.query(
      `INSERT INTO otp_tokens (user_id, otp_code, otp_type, purpose, expires_at)
       VALUES ($1, $2, $3, $4, $5)
       RETURNING id`,
      [userId, otpCode, method, purpose, expiresAt]
    );

    return {
      otpId: result.rows[0].id,
      otpCode,
      expiresAt,
    };
  }

  /**
   * Verify OTP submitted by user
   */
  async verifyOTP(userId, otpCode, purpose) {
    const result = await db.query(
      `SELECT id, otp_code, attempts, expires_at, is_used
       FROM otp_tokens
       WHERE user_id = $1 
         AND purpose = $2 
         AND is_used = FALSE
       ORDER BY created_at DESC
       LIMIT 1`,
      [userId, purpose]
    );

    if (result.rows.length === 0) {
      return { success: false, error: 'No active OTP found. Please request a new one.' };
    }

    const token = result.rows[0];

    // Check if expired
    if (new Date() > new Date(token.expires_at)) {
      await this.invalidateOTP(token.id);
      return { success: false, error: 'OTP has expired. Please request a new one.' };
    }

    // Check max attempts
    if (token.attempts >= OTP_CONFIG.maxAttempts) {
      await this.invalidateOTP(token.id);
      return {
        success: false,
        error: 'Too many failed attempts. Please request a new OTP.',
      };
    }

    // Verify code
    if (token.otp_code !== otpCode.toString()) {
      await db.query(
        `UPDATE otp_tokens SET attempts = attempts + 1 WHERE id = $1`,
        [token.id]
      );

      const remainingAttempts = OTP_CONFIG.maxAttempts - (token.attempts + 1);
      return {
        success: false,
        error: `Invalid OTP. ${remainingAttempts} attempt(s) remaining.`,
      };
    }

    // Mark OTP as used
    await this.invalidateOTP(token.id);

    return { success: true };
  }

  async invalidateOTP(otpId) {
    await db.query(
      `UPDATE otp_tokens SET is_used = TRUE WHERE id = $1`,
      [otpId]
    );
  }
}

module.exports = new OTPService();
```

