## 1️⃣ `otpService.js` — OTP Generator & Store

```javascript
const crypto = require("crypto");

// In-memory OTP store (use Redis in production)
const otpStore = new Map();

/**
 * Generate a secure numeric OTP
 * @param {number} length - OTP digit length (default: 6)
 * @returns {string}
 */
function generateOTP(length = 6) {
  const digits = "0123456789";
  let otp = "";
  for (let i = 0; i < length; i++) {
    otp += digits[crypto.randomInt(0, digits.length)];
  }
  return otp;
}

/**
 * Save OTP with expiry (5 minutes)
 * @param {string} identifier - email or phone number
 * @param {string} otp
 */
function saveOTP(identifier, otp) {
  const expiresAt = Date.now() + 5 * 60 * 1000; // 5 minutes
  otpStore.set(identifier, { otp, expiresAt, attempts: 0 });
  console.log(`[OTP] Saved OTP for ${identifier}: ${otp}`);
}

/**
 * Verify OTP
 * @param {string} identifier - email or phone number
 * @param {string} inputOTP
 * @returns {{ valid: boolean, message: string }}
 */
function verifyOTP(identifier, inputOTP) {
  const record = otpStore.get(identifier);

  if (!record) {
    return { valid: false, message: "OTP not found. Please request a new one." };
  }

  // Check expiry
  if (Date.now() > record.expiresAt) {
    otpStore.delete(identifier);
    return { valid: false, message: "OTP has expired. Please request a new one." };
  }

  // Check max attempts (max 3)
  if (record.attempts >= 3) {
    otpStore.delete(identifier);
    return { valid: false, message: "Too many failed attempts. Please request a new OTP." };
  }

  // Check OTP match
  if (record.otp !== inputOTP) {
    record.attempts += 1;
    otpStore.set(identifier, record);
    return { valid: false, message: `Incorrect OTP. ${3 - record.attempts} attempt(s) remaining.` };
  }

  // Valid! Clean up
  otpStore.delete(identifier);
  return { valid: true, message: "OTP verified successfully." };
}

/**
 * Check if OTP was recently sent (rate limiting - 60 seconds)
 * @param {string} identifier
 * @returns {boolean}
 */
function isRateLimited(identifier) {
  const record = otpStore.get(identifier);
  if (!record) return false;
  const cooldown = 60 * 1000; // 60 seconds
  return (record.expiresAt - 5 * 60 * 1000 + cooldown) > Date.now();
}

module.exports = { generateOTP, saveOTP, verifyOTP, isRateLimited };
```

