## 2️⃣ `smsService.js` — Send SMS OTP via Twilio

```javascript
const twilio = require("twilio");

const client = twilio(
  process.env.TWILIO_ACCOUNT_SID,
  process.env.TWILIO_AUTH_TOKEN
);

/**
 * Send OTP via SMS
 * @param {string} phoneNumber - E.164 format e.g. +1234567890
 * @param {string} otp
 * @returns {Promise}
 */
async function sendSMSOTP(phoneNumber, otp) {
  try {
    const message = await client.messages.create({
      body: `Your verification code is: ${otp}. It expires in 5 minutes. Do NOT share it.`,
      from: process.env.TWILIO_PHONE_NUMBER,
      to: phoneNumber,
    });

    console.log(`[SMS] OTP sent to ${phoneNumber}. SID: ${message.sid}`);
    return { success: true, sid: message.sid };
  } catch (error) {
    console.error(`[SMS] Failed to send OTP to ${phoneNumber}:`, error.message);
    return { success: false, error: error.message };
  }
}

module.exports = { sendSMSOTP };
```

